CREATE DATABASE IF NOT EXISTS genmove CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE genmove;
CREATE TABLE IF NOT EXISTS validation_runs (id INT AUTO_INCREMENT PRIMARY KEY, object_name VARCHAR(191) NOT NULL, source_file VARCHAR(500), target_file VARCHAR(500), status VARCHAR(20), summary_json LONGTEXT NOT NULL, created_at DATETIME NOT NULL, INDEX ix_validation_runs_object_name (object_name)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS field_results (id INT AUTO_INCREMENT PRIMARY KEY, run_id INT NOT NULL, field_name VARCHAR(191) NOT NULL, field_label VARCHAR(255), target_field VARCHAR(191), status VARCHAR(20), total INT, matched INT, mismatched INT, CONSTRAINT fk_field_run FOREIGN KEY (run_id) REFERENCES validation_runs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS record_results (id INT AUTO_INCREMENT PRIMARY KEY, run_id INT NOT NULL, field_name VARCHAR(191) NOT NULL, record_type VARCHAR(10) NOT NULL, record_key VARCHAR(500), source_value LONGTEXT, target_value LONGTEXT, result_detail VARCHAR(500), CONSTRAINT fk_record_run FOREIGN KEY (run_id) REFERENCES validation_runs(id) ON DELETE CASCADE, INDEX idx_record_drilldown (run_id, field_name, record_type, id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS uploaded_files (id INT AUTO_INCREMENT PRIMARY KEY, run_id INT, file_role VARCHAR(20) NOT NULL, file_path VARCHAR(500), created_at DATETIME NOT NULL, CONSTRAINT fk_upload_run FOREIGN KEY (run_id) REFERENCES validation_runs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS recommendations (id INT AUTO_INCREMENT PRIMARY KEY, run_id INT NOT NULL, field_name VARCHAR(191) NOT NULL, target_field VARCHAR(191), severity VARCHAR(20), affected_records INT, explanation LONGTEXT, CONSTRAINT fk_recommendation_run FOREIGN KEY (run_id) REFERENCES validation_runs(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS correction_rules (id INT AUTO_INCREMENT PRIMARY KEY, object_name VARCHAR(191) NOT NULL, source_field VARCHAR(191) NOT NULL, target_field VARCHAR(191) NOT NULL, action VARCHAR(100) NOT NULL, approved_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit_log (id INT AUTO_INCREMENT PRIMARY KEY, level VARCHAR(20), message LONGTEXT NOT NULL, created_at DATETIME NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, display_name VARCHAR(255) NOT NULL, password_hash VARCHAR(500) NOT NULL, active INT NOT NULL DEFAULT 1, created_at DATETIME NOT NULL, last_login DATETIME NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transformation_rules (id INT AUTO_INCREMENT PRIMARY KEY, object_name VARCHAR(191) NOT NULL, name VARCHAR(255) NOT NULL, source_field VARCHAR(191) NOT NULL, target_field VARCHAR(191) NOT NULL, source_value VARCHAR(500) NOT NULL, target_value VARCHAR(500) NOT NULL, description LONGTEXT, status VARCHAR(40) NOT NULL, version VARCHAR(30) NOT NULL, created_by VARCHAR(255), approved_by VARCHAR(255), created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, INDEX ix_transformation_rules_object_name (object_name), INDEX ix_transformation_rules_status (status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS transformation_jobs (id INT AUTO_INCREMENT PRIMARY KEY, object_name VARCHAR(191) NOT NULL, source_file VARCHAR(500) NOT NULL, output_file VARCHAR(500), status VARCHAR(40) NOT NULL, applied_rules INT, changed_rows INT, changed_cells INT, created_by VARCHAR(255), audit_json LONGTEXT, created_at DATETIME NOT NULL, INDEX ix_transformation_jobs_object_name (object_name)) ENGINE=InnoDB;
